mapper.select:
SELECT id, country_code AS countryCode, alpha3_code AS alpha3Code, numeric_code AS numericCode, name, region_code AS regionCode, calling_code AS callingCode, default_currency_code AS defaultCurrencyCode, logo_file_address AS logoFileAddress, status, version, create_time AS createTime, update_time AS updateTime FROM t_ref_country
AND status = #{status}
AND country_code IN #{code}
ORDER BY country_code
